INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Maybelline Lash Sensational Sky High Noir – Mascara Longueur = Crayon Tattoo Studio 900 Deep Onyx Offert','Maybelline','Maquillage','Maybelline Lash Sensational Sky High Noir – Mascara Longueur + Crayon Tattoo Studio 900 Deep Onyx Offert

