INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Maybelline Sky High Air Rose – Mascara Volume & Longueur = Crayon Tattoo liner  Studio Ultra Pink Offert','Maybelline','Maquillage','Maybelline Sky High Air Rose – Mascara Volume & Longueur + Crayon Tattoo Studio Ultra Pink Offert

