INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('COLLAGENLIFT® 20 sachet','Collagenlift','Visage','CollagenLift® est un complément alimentaire formulé pour agir de l''intérieur sur les principaux signes du vieillissement cutané. Sa formule associe les peptides de collagène bioactifs VERISOL®, de l''acide hyaluronique, de la vitamine C, du zinc, du cuivre, de la biotine et du resvératrol afin de soutenir la beauté et la santé de la peau.
Grâce à la technologie VERISOL®, des peptides de collagène spécifiques et hautement biodisponibles, CollagenLift® stimule naturellement la production de collagène et contribue à améliorer l''élasticité, la fermeté et l''hydratation de la peau tout en aidant à réduire l''apparence des rides.',28500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Collagenlift_1.png?v=1785933524',10,1,'8657580949679','47311183511727','https://beautymarket.ma/products/collagenlift®-20-sachet',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Collagenlift_1.png?v=1785933524"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HELEXINA RENOV Crème Visage 50ml','Helexina','Visage','Helexina Renov Crème est un soin anti-âge conçu pour hydrater intensément la peau tout en aidant à corriger les signes visibles du vieillissement. Sa formule associe des peptides biomimétiques, des peptides Botox-like, et de l''acide hyaluronique pour une action complète sur les rides, la fermeté et l''éclat de la peau.

Conseils d''utilisation
