INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HELEXINA RENOV Serum Visage 50ml','Helexina','Cheveux','Helexina Renov Sérum est un sérum anti-âge concentré qui aide à atténuer les signes visibles du vieillissement cutané. Sa formule associe des peptides biomimétiques, des peptides Botox-like, de l''acide hyaluronique, de la bave d''escargot, de l''Edelweiss et un extrait de quinoa pour hydrater intensément, lisser les rides et améliorer la fermeté de la peau.

Conseils d''utilisation
Appliquer 1 à 2 gouttes matin et soir sur le visage et le cou parfaitement propres. Masser délicatement jusqu''à absorption complète, puis appliquer Helexina Renov Crème pour compléter la routine.',38000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Image3fsdsc_1.png?v=1785933915',10,1,'8657584095407','47311194325167','https://beautymarket.ma/products/helexina-renov-serum-visage-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Image3fsdsc_1.png?v=1785933915"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Toconorm Gouttes Buvables Vitamine E 30ml','Toconorm','Bien-être','Toconorm® est un complément alimentaire à base de vitamine E naturelle (d-α-tocophérol), sous forme de gouttes buvables, spécialement conçu pour répondre aux besoins en vitamine E de toute la famille. Sa forme liquide facilite l''administration et permet un dosage précis, adapté aux nourrissons, aux enfants et aux adultes.

Conseils d''utilisation
Utiliser selon les recommandations de votre professionnel de santé ou selon la posologie indiquée sur l''emballage. Les gouttes peuvent être prises directement ou mélangées à une boisson ou à un aliment froid.',14000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/sfqdqsdqsd_1.png?v=1785932961',10,1,'8657584521391','47311197077679','https://beautymarket.ma/products/toconorm-gouttes-buvables-vitamine-e-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/sfqdqsdqsd_1.png?v=1785932961"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DANCOLY PARIS PACK AU MIEL DE MANUKA SHAMPOING 450 ML + MASQUE 450 ML','Dancoly Paris','Cheveux','Ce kit généreux comporte le shampoing et le mask au miel pur de Manuka.

Sans SULFATES - Sans PARABENS - INGRÉDIENTS BIO

Shampoing 450 ml Le Miel de Manuka est un anti-oxydant. La protéase de Miel contient une grande quantité d’anti-oxydants qui supprime les radicaux libres présents dans les cheveux permettant de lutter contre l’oxydation et le vieillissement prématuré de vos cheveux. La propolis est riche en collagènes actifs qui répare les cheveux abîmés.

Mode d’emploi : Appliquer sur les cheveux mouillés ; masser votre cuir chevelu et vos cheveux doucement, puis rincer abondamment. A utiliser avec Masque capillaire au Miel de Manula pour un meilleur résultat.

Mask 450 ml Contenant du Miel de Manuka, de l’huile de fleur de Rosier cent-feuilles, de l’huile de beurre de Karité, de l’huile de pépins de raisin, ce masque est spécialement adapté pour les cheveux secs et abîmés. Riche en essence de propolis naturelle, ce précieux mélange répare vos cheveux abîmés et apporte un soin professionnel et approfondi à vos cheveux. Vos cheveux deviennent lisses et faciles à coiffer tout en ayant une brillance face à la lumière.

Mode d’emploi : Après application du shampooing, prenez une dose du masque dans la paume de votre main. Frottez vos mains conjointement et massez à partir des racines de vos cheveux jusqu’aux pointes de manière uniforme. Utilisez de la vapeur ou couvrez vos cheveux avec une serviette chaude. Laissez 10-15 minutes. Rincez abondamment.',76000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/edbb030a-d781-4ae3-94cc-7748f9bec703-thumbnail-1000x1000-70.jpg?v=1786012993',10,1,'8659014418607','47317175861423','https://beautymarket.ma/products/dancoly-paris-pack-au-miel-de-manuka-shampoing-450-ml-masque-450-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/edbb030a-d781-4ae3-94cc-7748f9bec703-thumbnail-1000x1000-70.jpg?v=1786012993","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/F410EF03-79DB-43CF-8809-3E09BF5A7323.jpg?v=1786013021","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/26A0AEC5-98BA-46DC-873A-F7CFCE0E64C5.webp?v=1786013024"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
