INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ORAL-B BROSSE À DENTS SENSITIVE CARE EXTRA SOFT','Oral-B','Hygiène','Brins micro-fendus pour un nettoyage doux et en profondeur

