INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CREST PRO 3D WHITE CLINICAL GLAMROUS WHITE 1 DAY 75 ML','Crest','Hygiène','Le dentifrice Crest Pro 3D White Clinical Glamorous White 1 Day est conçu pour aider à éliminer les taches superficielles et à révéler un sourire visiblement plus blanc. Sa formule blanchissante offre un nettoyage efficace tout en aidant à préserver l’éclat naturel des dents.

