INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION AIR BLUR MATTE LIQUID LIPSTICK Chauffeur','Revolution','Maquillage','Les rouges à lèvres mats sont de retour! La gamme Air Blur vous promet des lèvres audacieuses!

