INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('essence Club Soleil Lip Stain 01 Tan-tastic!','Essence','Autres soins','essence Club Soleil Lip Stain 01 Tan-tastic!

