INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('L’oréal Paris Elseve Pack Huile Extraordinaire Jojoba 100 Ml + Shampooing 400 Ml + Brosse Offerte','L''Oréal Paris','Cheveux','le Soin Transformateur Disciplinant Elsève Huile Extraordinaire de L’Oréal Paris, un véritable élixir de beauté pour vos cheveux. Enrichie en huile de jojoba, cette formule innovante métamorphose instantanément vos cheveux ternes en une matière extraordinaire, les laissant brillants, intensément nourris et parfaitement disciplinés.

