INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('L''Oréal Paris Elseve Pack Extra Midnight Serum 100ml + Shampooing 400 ml Cheveux Normaux A Secs = Brosse Offerte','L''Oréal Paris','Cheveux','L''oréal paris elseve extra midnight serum 100ml

