INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Revuele Go Glow! Exfoliant Doux Éclat aux Vitamines C, E et F 80ML','Revuele','Visage','Go Glow! Gentle Exfoliant 80 ml est un gommage visage revitalisant enrichi d’un puissant mélange de vitamines C, E et F. Sa formule douce élimine efficacement les cellules mortes de la peau, révélant un teint plus lisse et plus éclatant. Adapté à tous les types de peau, cet exfoliant aide à illuminer la peau, améliorer sa texture et restaurer un éclat sain.

