INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Revuele Go Glow! Power Sérum Éclat aux Vitamines C, E et F 30ML','Revuele','Visage','Go Glow! Power Serum 30 ml est un sérum visage revitalisant enrichi d’un puissant mélange de vitamines C, E et F. Cette formule légère et rapidement absorbée est conçue pour améliorer l’éclat de la peau, unifier le teint et offrir une protection antioxydante. Idéal pour une utilisation quotidienne, il aide à obtenir un teint sain et lumineux.

