INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Revuele Pore Slayer Power Sérum Anti-Imperfections aux Céramides et Zinc 30 ml','Revuele','Visage','Le sérum PORE SLAYER POWER SERUM CERAMIDES + ZINC 30 ml soyeux à absorption rapide, est enrichi en céramides et en zinc, affine la texture de la peau et renforce la barrière cutanée. Il cible les pores obstrués et les imperfections, révélant un teint plus lisse, plus net et plus équilibré.
