INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Revuele Shampooing Renforce et Répare les Cheveux Secs et Abîmés Anti-Frisottis 250ML','Revuele','Cheveux','souplesse et répare intensément les cheveux abîmés pour une résistance optimale.
