INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Revuele Filler Day Crème de Jour Repulpante et Hydratante 50 ml','Revuele','Visage','hydrater, lisser et repulper la peau. Elle aide à soutenir les fonctions naturelles de la peau, à maintenir son équilibre et à lui apporter une hydratation suffisante pour une apparence plus fraîche et plus saine.

