INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bioderma Pack Photoderm XDefense Teinte 01 = Sensibio H2O 100ml Offert','Bioderma','Solaires','Coffret Bioderma Photoderm XDefense Teinte 01 = Sensibio H2O 100ml Offert

