INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DR BANGGIWON SHAMPOOING ANTIPELLICULAIRE 1000ML','Dr Banggiwon','Cheveux','Soin professionnel du cuir chevelu pour combattre les pellicules et réduire la perte de cheveux — dans un flacon généreux de taille salon.

