INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LACTOVIT DEODORANT PIEL SENSIBLE SPRAY 72H 200ML','LACTOVIT','Corps','Le déodorant Piel Sensible de Lactovit prend soin et protège l''aisselle grâce à sa technologie brevetée exclusive à base de microcapsules Lactoprotect.

Cette technologie unique d''encapsulation permet une libération contrôlée des ingrédients actifs, qui s''activent uniquement lorsque le corps en a besoin (situation stressante, activité physique, changements de température).

Grâce aux composants essentiels du lait, il minimise le risque d''irritation tout en contrôlant efficacement la transpiration et les mauvaises odeurs. Sa formule sans alcool prend soin de la peau au quotidien, offrant une protection maximale contre la transpiration pendant 48h.',3900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/61AhuzltQnL.jpg?v=1789825492',10,1,'8706879422639','47537708859567','https://beautymarket.ma/products/lactovit-deodorant-piel-sensible-spray-72h-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/61AhuzltQnL.jpg?v=1789825492"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LACTOVIT DÉODORANT SPRAY EXTRA EFICAZ INVISIBLE 72H 200ML','LACTOVIT','Corps','Le déodorant spray Extra Eficaz soigne et protège l''aisselle grâce à sa formule au ProLactiC10 et sa double technologie brevetée, qui renforce la peau contre les irritations.

 Il offre une protection maximale contre la transpiration pendant 72h, de façon invisible, sans alcool éthylique, en maintenant la peau soignée et sans inconfort. Grâce à sa formule exclusive, il stimule également la synthèse de collagène et d''élastine, offrant une peau hydratée, élastique et ferme. Dès la première utilisation, les aisselles sont plus douces et plus soignées — la dose quotidienne de force pour la peau : peau forte, peau jeune, peau 50% plus forte contre les irritations.',3900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8411135352155_872e.jpg?v=1789826233',10,1,'8706882371759','47537714004143','https://beautymarket.ma/products/lactovit-deodorant-spray-extra-eficaz-invisible-72h-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8411135352155_872e.jpg?v=1789826233"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
