INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SUBTIL BIPHASE VIOLET DÉMÊLANT BLONDS 200ML','Subtil','Cheveux','Soin démêlant instantané raviveur d''éclat spécial cheveux blond, gris et blancs. Le geste beauté pour prévenir le ternissement : aux Baies de l''Arctique et doté d''un agent déjaunisseur, ce soin neutralise les effets jaunes. Les reflets corrigés, les cheveux gris ou blonds retrouvent tout leur éclat et leur brillance.',21900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/subtil-biphase-violet-subtil-soin-bi-phase-demelant-cheveux-blonds-ou-blancs-anti-reflets-jaunes-200ml.jpg?v=1789995761',10,1,'10312144847023','50512865296559','https://beautymarket.ma/products/subtil-biphase-violet-demelant-blonds-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/subtil-biphase-violet-subtil-soin-bi-phase-demelant-cheveux-blonds-ou-blancs-anti-reflets-jaunes-200ml.jpg?v=1789995761"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SUBTIL SPRAY COIFFURE ET MAQUILLAGE BLOND FONCE 75ML','Subtil','Cheveux','Pour que l’effet racine disgracieux entre deux colorations ne soit plus qu’un lointain souvenir, optez pour les sprays HAIR MAKE UP! de Subtil, des sprays teintés qui effaceront en un seul geste les racines

C’est grâce à l’action de pigments intenses et vibrants combinée à la présence de résine que les sprays HAIR MAKE UP! se fondront parfaitement avec votre teinte.

La démarcation entre les racines et la couleur est instantanément camoufler, le résultat se veut naturel et fondu.

Pratique d’utilisation, les sprays retouches racines de Subtil résistent également à l’humidité et apporte une tenue irréprochable jusqu’au prochain shampoing',19900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SubtilTouchUp_darkBlond_web_1000x1000_de801ec8-b825-4ecf-ac77-45c3d56e9929.webp?v=1790002449',10,1,'10312210186415','50513196744879','https://beautymarket.ma/products/subtil-spray-coiffure-et-maquillage-blond-fonce-75ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SubtilTouchUp_darkBlond_web_1000x1000_de801ec8-b825-4ecf-ac77-45c3d56e9929.webp?v=1790002449"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SUBTIL SCIENTIST SHAMPOOING ÉQUILIBRE ANTIPELLICULAIRE 300ml','Subtil','Cheveux','Enrichi en extrait d’écorce de Grenade, ce shampooing permet d’assainir et de rééquilibrer le cuir chevelu.

Sa formule douce à 93% d’ingrédients d’origine naturelle élimine les pellicules, tout en apaisant les démangeaisons.

RÉSULTAT Exit les pellicules disgracieuses et les sensations d’inconfort : votre chevelure retrouve toute sa légèreté.

MODE D''EMPLOI :

Appliquer sur cheveux mouillés.

Masser délicatement, laisser agir quelques minutes.

Rincer soigneusement.',19900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/scientist-equilibre-shampooing-antipelliculaire-300ml.jpg?v=1790002733',10,1,'10312769405103','50515832733871','https://beautymarket.ma/products/subtil-scientist-shampooing-equilibre-antipelliculaire-300ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/scientist-equilibre-shampooing-antipelliculaire-300ml.jpg?v=1790002733"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
