INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LIRENE SCRUB COFFEE NO MORE DRAMA 175G','Lirene','Corps','Le Lirene Coffee Scrub No More Drama est un gommage corporel énergisant formulé à base de café moulu naturel et d’ingrédients nourrissants pour exfolier la peau en douceur. Il élimine les cellules mortes, stimule la microcirculation et laisse la peau douce, lisse et délicatement parfumée. Enrichi en huiles végétales (amande douce, noix de coco) et en vitamine E, ce soin aide à raffermir la peau tout en améliorant sa texture et son éclat. Parfait pour une peau plus tonique, éclatante et visiblement plus lisse.',4900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/NOMOREDRAMA.jpg?v=1790069664',10,1,'10313442787503','50519724556463','https://beautymarket.ma/products/lirene-scrub-coffee-no-more-drama-175g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/NOMOREDRAMA.jpg?v=1790069664"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
