INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('La roche posay pack effaclar gel moussant 200 ml + éco-recharge 400ml','La Roche-Posay','Visage','La Roche Posay Effaclar Gel Moussant 200 Ml +

