INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('K18 PEPTIDE PREP SHAMPOOING DETOXIFIANT 53 ML','K18','Cheveux','Un shampooing clarifiant sans danger pour la couleur et non décapant avec le K18PEPTIDE™ pour éliminer en douceur mais efficacement 99 % des accumulations de produit*, 95 % de sébum* + 76 % de cuivre* pour des cheveux détoxifiés et rafraîchis.

