INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bambino Natural Baby Biberon +0m Bleu 150ml','BAMBINO','Bébé & Maman','En plus de l’allaitement, il est utilisé pendant les périodes où l’allaitement au biberon est nécessaire ou ne peut pas être allaité. Il est soigneusement fabriqué à partir de polypropylène.

