INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('GARNIER ULTRA DOUX DUO RICE WATER HAIR SILK SERUM 120ML + SHAMPOOING D’EAU DE RIZ & AMIDON 400ML','Garnier','Cheveux','Découvrez le pack Garnier Ultra Doux Rice Water, une routine inspirée des rituels asiatiques pour des cheveux lisses, brillants et soyeux.

